        t.min_restantes = 0 if t.hecho else t.minutos
        if t.hecho:
            t.piezas_antes_check = 0
            if t.fecha_cierre and not t.cerrada_al_archivar:
                t.cierre = "CHECK"
        t.save(update_fields=["min_restantes", "piezas_antes_check", "cierre"])


